async function queueAndRun(command, options) {
  const { waitS, staleS, light, staticRun, priority, project, size, park, attempt } = options
  const scopeGuard = lightScopeGuard(command, { light, staticRun })
  if (scopeGuard.refused) return 2
  const waiting = watchSuiteWaitSignals()
  try {
    const reservation = process.platform !== 'win32' && !park && !staticRun && !process.env.WT_SUITE_LOCK_BROKER
    if (process.platform === 'win32') process.stderr.write('wt-suite-lock: memory watchdog unknown (unsupported-platform-memory-and-load); using exclusive protocol\n')
    const lease = await acquireCliLease(acquireParkCliLease(acquireSuiteLock, park), { waitS, staleS, argv: command, replaceable: !park && !light && !staticRun, light, static: staticRun, priority, project, size, reservation, requeue: options.requeue, signal: waiting.signal, offload: true, onOffloadLog: (chunk) => process.stdout.write(chunk), onWait: (line) => process.stderr.write(`${line}\n`) })
    if (typeof lease === 'number') return lease
    if (lease.offloaded) { process.stderr.write(`wt-suite-lock: offloaded; archive ${lease.offloaded.archive}\n`); return lease.offloaded.exit }
    const timing = {}
    try {
      const exit = await runLeasedCommand(lease.replacementArgv ?? command, lease, { light, staticRun, park, attempt, timing, waiting })
      if (timing.requeue && !timing.stopUnconfirmed && !timing.releaseFailed) options.retry = lease
      return exit
    } finally { scopeGuard.end(timing.heldMs) }
  } catch (error) {
    if (suiteSignalExit(waiting.signal.reason)) return suiteSignalExit(waiting.signal.reason)
    throw error
  } finally { waiting.close() }
}

